candidate.css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --panel2:#1d2140;
  --text:#e9ecff;
  --muted:#b8bde6;
  --faint:#8a90c7;
  --accent:#7bdcff;
  --good:#7dffb2;
  --warn:#ffd27d;
  --bad:#ff7d9c;
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%);color:var(--text);font-family:var(--sans)}
.wrap{max-width:980px;margin:0 auto;padding:18px 16px 28px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:20px;line-height:1.2;margin:0 0 6px}
.sub{margin:0;color:var(--muted);font-size:13px;max-width:78ch}
.panel{background:linear-gradient(180deg, var(--panel) 0%, #13162a 100%);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:14px 14px 12px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.row.small{margin-top:10px;gap:14px}
.lbl{font-size:12px;color:var(--muted);min-width:92px}
.inp{flex:1;min-width:220px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);color:var(--text);padding:10px 10px;border-radius:10px;font-size:16px;outline:none}
.inp:focus{border-color:rgba(123,220,255,.55);box-shadow:0 0 0 3px rgba(123,220,255,.12)}
.btn{background:linear-gradient(180deg, rgba(123,220,255,.95), rgba(123,220,255,.75));border:none;color:#07101a;padding:10px 12px;border-radius:10px;font-weight:700;cursor:pointer}
.btn:hover{filter:brightness(1.05)}
.btn:active{transform:translateY(1px)}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,.18);color:var(--text);font-weight:600}
.btn.ghost:hover{border-color:rgba(123,220,255,.45)}
.tog{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}
.tog input{accent-color:var(--accent)}
.out{margin-top:12px;padding:12px;border-radius:12px;background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.03));border:1px solid rgba(255,255,255,.10)}
.kv{display:grid;grid-template-columns:160px 1fr;gap:8px 12px;align-items:start}
.k{color:var(--faint);font-size:12px}
.v{font-size:14px}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;font-size:12px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.06);margin-right:6px}
.badge.good{border-color:rgba(125,255,178,.35);color:var(--good)}
.badge.warn{border-color:rgba(255,210,125,.35);color:var(--warn)}
.badge.bad{border-color:rgba(255,125,156,.35);color:var(--bad)}
.mono{font-family:var(--mono)}
.hr{height:1px;background:rgba(255,255,255,.10);margin:10px 0}
.grid{display:grid;grid-template-columns:1.1fr 1fr 1fr;gap:12px}
@media (max-width:900px){.grid{grid-template-columns:1fr}}
.card{background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.03));border:1px solid rgba(255,255,255,.10);border-radius:12px;padding:12px}
.card h3{margin:0 0 10px;font-size:14px}
.help{margin:0 0 10px;color:var(--muted);font-size:13px}
.tiny{color:var(--muted);font-size:12px;margin:8px 0 0}
.bul{margin:8px 0 0 18px;color:var(--muted);font-size:13px}
.ftr{margin-top:10px;color:var(--muted);font-size:12px;text-align:center}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{padding:7px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.16);background:rgba(255,255,255,.05);cursor:pointer;font-size:13px;color:var(--text)}
.chip[aria-pressed="true"]{border-color:rgba(123,220,255,.55);box-shadow:0 0 0 3px rgba(123,220,255,.12)}
.genOut{margin-top:10px;min-height:44px;padding:10px;border-radius:10px;border:1px dashed rgba(255,255,255,.18);color:var(--text)}
.syll{display:inline-block;padding:2px 6px;border-radius:8px;background:rgba(123,220,255,.10);border:1px solid rgba(123,220,255,.18);margin:2px 4px 2px 0;font-family:var(--mono);font-size:13px}
.note{color:var(--muted);font-size:13px;margin-top:6px;line-height:1.35}
.warnbox{padding:10px;border-radius:10px;border:1px solid rgba(255,210,125,.25);background:rgba(255,210,125,.08);color:var(--text)}
.goodbox{padding:10px;border-radius:10px;border:1px solid rgba(125,255,178,.25);background:rgba(125,255,178,.08);color:var(--text)}
.badbox{padding:10px;border-radius:10px;border:1px solid rgba(255,125,156,.25);background:rgba(255,125,156,.08);color:var(--text)}
.inp{min-width:0;max-width:100%;width:100%}.v,.card{min-width:0;overflow-wrap:anywhere}.kv{grid-template-columns:minmax(100px,160px) minmax(0,1fr)}@media(max-width:540px){.wrap{padding:14px 10px}.kv{grid-template-columns:1fr}.row>.inp{flex-basis:100%}.grid{grid-template-columns:1fr}.card .inp{display:block}.lbl{min-width:0}}

