const $ = (sel) => document.querySelector(sel);

const examples = [
  "Σινωπίτης","Ἰοπίτης","Ἀκεσίτης","Παγασίτης","Ἀκμονίτης","Ἀβδηρίτης","Γαβαλίτης","Διολκίτης","Μεμφίτης","Ναυκρατίτης",
  "εὐρείτης","βαθυρρείτης","ἀκαλαρείτης","ἱερείτης","Σαμαρείτης","Ἀταρνείτης","Ἑλείτης","Ἁγνωνείτης","Μαρωνείτης","Καυκωνείτης",
  "Δικαιαρχείτης","Ζελείτης","Ὠρείτης","ἀλείτης","ἀλοίτης",
  "τραπεζίτης","τραπεζείτης","τραπεζήτης",
  "πρεσβύτης","ἐλύτης","βασανύτης","ἁλκυονύτης","Ἀρχύτης","Πιδύτης","Αἰγύτης","Κωβρύτης","Μωλύτης","Αἰπύτης","Πατρασύτης",
  "Δαμοίτης","Μενοίτης","Θυμοίτης","Ἀγροίτης","Φιλοίτης","Λαοίτης","Ἀνεμοίτης","Ὀροίτης","Ἀνδροίτης","Σακοίτης","Ζιποίτης",
  "Βουτοίτης","Σαβοίτης","Κυβοίτης",
  "Μαντούτης","τριακοντούτης",
  "ὑφάντης","ἀγύρτης","εὐφράντης","ὀξύντης","ἐγέρτης","ὀρίντης","αὐθέντης","Λαέρτης","Σιβύρτης","Βερεκύντης"
];

// --- Polytonic helpers (approximate) ---
const COMBINING = /[\u0300-\u036f]/g;
function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripDiacritics(s){
  // remove combining marks; keep base letters
  return nfc(nfd(s).replace(COMBINING, ''));
}

function lowerGreek(s){
  return s.toLocaleLowerCase('el');
}

function endsWithAny(word, suffixes){
  for(const suf of suffixes){
    if(word.endsWith(suf)) return suf;
  }
  return null;
}

// Very rough syllabifier: split before vowel groups.
const VOW = "αεηιουω";
function isVowel(ch){ return VOW.includes(ch); }
function roughSyllables(word){
  const w = stripDiacritics(lowerGreek(word)).replace(/[^\p{L}]/gu,'');
  if(!w) return [];
  // Build chunks: onset+vowelgroup+coda until next vowelgroup
  let syl = [];
  let cur = "";
  let i=0;
  while(i<w.length){
    cur += w[i];
    // if current char is vowel, absorb following vowels (diphthong-ish)
    if(isVowel(w[i])){
      while(i+1<w.length && isVowel(w[i+1])){ cur += w[i+1]; i++; }
      // then absorb following consonants up to (but not including) next vowel
      while(i+1<w.length && !isVowel(w[i+1])){
        // stop if next-next is vowel: leave one consonant for onset (very rough)
        if(i+2<w.length && isVowel(w[i+2])) break;
        cur += w[i+1]; i++;
      }
      syl.push(cur);
      cur = "";
    }
    i++;
  }
  if(cur) syl.push(cur);
  return syl.filter(x=>x.length);
}

// Accent placement: add acute to first vowel of target syllable.
const ACUTE_MAP = {
  'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
  'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
};
function addAcuteToFirstVowel(s){
  // operate on NFC Greek; if already has tonos/polytonic, we still try after stripping
  const base = stripDiacritics(s);
  let out = "";
  let done = false;
  for(const ch of base){
    if(!done && ACUTE_MAP[ch]){ out += ACUTE_MAP[ch]; done = true; }
    else out += ch;
  }
  return out;
}

const keyOf=s=>stripDiacritics(lowerGreek(s)).trim();
const attested=new Map([...examples,'κωλυτής','μηνυτής'].map(w=>[keyOf(w),w.normalize('NFC')]));
function stripAccents(s){return s.normalize('NFD').replace(/[\u0300\u0301\u0342]/g,'').normalize('NFC');}
function barytoneSuggest(word){
  const syl=roughSyllables(word), known=attested.get(keyOf(word));
  if(known)return {suggestion:known,target:null,syl,basis:'cited form in passage 1.77'};
  if(!$('#stripAcc').checked && /[\u0300\u0301\u0342]/.test(word.normalize('NFD')))
    return {suggestion:word,target:null,syl,basis:'supplied accent retained; not verified'};
  const chars=Array.from(stripAccents(word).normalize('NFD').matchAll(/[^\p{M}]\p{M}*/gu),m=>m[0]);
  const nuclei=[];
  for(let i=0;i<chars.length;i++){
    const a=keyOf(chars[i]);if(!VOW.includes(a)||a.length!==1)continue;
    const b=chars[i+1]?keyOf(chars[i+1]):'';
    if(['αι','ει','οι','υι','αυ','ευ','ηυ','ου'].includes(a+b) && !chars[i+1].includes('\u0308'))i++;
    nuclei.push(i);
  }
  if(nuclei.length<2)return {suggestion:word,target:null,syl,basis:'no nonfinal accent proposed'};
  const index=nuclei[nuclei.length-2];chars[index]+='\u0301';
  return {suggestion:chars.join('').normalize('NFC'),target:null,syl,basis:'illustrative penult accent; not a lexical prediction'};
}

function classify(word){
  const w = stripDiacritics(lowerGreek(word)).replace(/\s+/g,'');
  const suf = endsWithAny(w, ["οιτης","ουτης","υτης","ειτης","ιτης","της"]);
  let cls = {suffix:suf, barytone:null, note:[]};

  if(!suf){
    cls.barytone = null;
    cls.note.push("No -της-type ending detected.");
    return cls;
  }

  const listed=attested.has(w);
  if(w==='κωλυτης'||w==='μηνυτης'){
    cls.barytone=false;
    cls.note.push('Explicit exception: κωλυτής and μηνυτής are verbal, not members of the long-υ derivative class. Their cited accent is on the ultima.');
  }else if(suf==='ουτης'){
    cls.barytone=true;cls.note.push('The passage says -ουτης forms are barytone; Μαντούτης and τριακοντούτης are its examples.');
  }else if(suf==='οιτης'){
    cls.barytone=listed?true:null;cls.note.push('The rule requires isosyllabic -οιτης forms. An unfamiliar ending alone does not establish that condition.');
  }else if(suf==='υτης'){
    cls.barytone=listed?true:null;cls.note.push('The rule requires a derivative with long υ; the suffix alone establishes neither quantity nor derivation.');
  }else if(suf==='ειτης'||suf==='ιτης'){
    cls.barytone=listed?true:null;cls.note.push(listed?'A cited form: use the passage spelling shown below.':'No general rule is inferred for an unfamiliar -ιτης or -ειτης form.');
  }else{
    cls.barytone=listed?true:null;cls.note.push('The plain -της rule requires a penult ending in an unchangeable consonant, no σ in the genitive, and a non-participial form. Unknown words need those checks.');
  }

  // τραπεζιτης fork
  const bare = stripDiacritics(w);
  if(bare === "τραπεζιτης" || bare === "τραπεζειτης" || bare === "τραπεζητης"){
    cls.note.push("τραπεζίτης fork: ‘market/banker’ is τραπεζίτης (from τράπεζα); ‘dog’ is τραπεζείτης (from τραπεζεύς); τραπεζήτης in Ibycus (ει→η). Try toggling spelling below.");
  }

  return cls;
}

function render(){
  const raw = $('#inp').value.trim();
  const ignore = $('#stripAcc').checked;
  const showSyll = $('#showSyll').checked;
  const showRules = $('#showRules').checked;

  if(!raw){
    $('#out').innerHTML = `<div class="warnbox">Type a Greek word ending in <span class="mono">-της</span> (or <span class="mono">-οιτης</span>, <span class="mono">-ουτης</span>, <span class="mono">-υτης</span>), e.g. <span class="mono">Δαμοίτης</span> or <span class="mono">Μαντούτης</span>.</div>`;
    return;
  }

  const inputForAnalysis = ignore ? stripDiacritics(raw) : raw;
  const cls = classify(inputForAnalysis);
  const sug = barytoneSuggest(raw);
  if(!cls.suffix){sug.suggestion='No supported suffix — no accent proposed.';sug.basis='outside this workshop’s suffix classes';}

  let badges = [];
  if(cls.suffix){
    badges.push(`<span class="badge good">suffix: -${cls.suffix}</span>`);
  } else {
    badges.push(`<span class="badge bad">no -της suffix detected</span>`);
  }
  if(cls.barytone === true) badges.push(`<span class="badge good">barytone class</span>`);
  else if(cls.barytone === false) badges.push(`<span class="badge bad">not barytone</span>`);
  else badges.push(`<span class="badge warn">needs morphology</span>`);

  const sylHtml = showSyll && sug.syl.length
    ? `<div class="v">${sug.syl.map((s,i)=>`<span class="syll" title="syllable ${i+1}">${s}</span>`).join('')}</div>`
    : `<div class="v"><span class="badge warn">(syllables hidden)</span></div>`;

  // τραπεζιτης switcher
  const bare = stripDiacritics(lowerGreek(inputForAnalysis)).replace(/[^\p{L}]/gu,'');
  let fork = '';
  if(['τραπεζιτης','τραπεζειτης','τραπεζητης'].includes(bare)){
    const baseStem = 'τραπεζ';
    fork = `
      <div class="hr"></div>
      <div class="kv">
        <div class="k">τραπεζίτης toy fork</div>
        <div class="v">
          <button class="btn ghost" data-fork="τραπεζιτης">τραπεζίτης (ι)</button>
          <button class="btn ghost" data-fork="τραπεζειτης">τραπεζείτης (ει)</button>
          <button class="btn ghost" data-fork="τραπεζητης">τραπεζήτης (η)</button>
          <div class="note">Click to replace your input with one of Herodian’s spellings and re-run.</div>
        </div>
      </div>
    `;
  }

  const notes = showRules ? cls.note.map(n=>`<div class="note">• ${n}</div>`).join('') : '';

  $('#out').innerHTML = `
    <div class="kv">
      <div class="k">Input (as analyzed)</div>
      <div class="v"><span class="mono">${escapeHtml(inputForAnalysis)}</span></div>

      <div class="k">Flags</div>
      <div class="v">${badges.join(' ')}</div>

      <div class="k">Rough syllables</div>
      ${sylHtml}

      <div class="k">Cited form / toy suggestion</div>
      <div class="v"><span class="mono">${escapeHtml(sug.suggestion)}</span> <span class="badge warn">${escapeHtml(sug.basis)}</span></div>

      <div class="k">Unaccented form</div>
      <div class="v"><span class="mono">${escapeHtml(stripDiacritics(inputForAnalysis))}</span></div>
    </div>
    ${fork}
    ${notes ? `<div class="hr"></div>${notes}` : ''}
  `;

  // bind fork buttons if present
  $('#out').querySelectorAll('button[data-fork]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const v = btn.getAttribute('data-fork');
      // display with polytonic-ish accents for the three known forms
      const pretty = (v === 'τραπεζιτης') ? 'τραπεζίτης'
        : (v === 'τραπεζειτης') ? 'τραπεζείτης'
        : 'τραπεζήτης';
      $('#inp').value = pretty;
      render();
    });
  });
}

function escapeHtml(s){
  return String(s)
    .replaceAll('&','&amp;')
    .replaceAll('<','&lt;')
    .replaceAll('>','&gt;')
    .replaceAll('"','&quot;')
    .replaceAll("'",'&#39;');
}

// --- Generator mini-game ---
const suffixOptions = [
  {id:'ιτης', label:'-ίτης / -ιτης', suf:'ιτης'},
  {id:'ειτης', label:'-είτης / -ειτης', suf:'ειτης'},
  {id:'οιτης', label:'-οίτης / -οιτης', suf:'οιτης'},
  {id:'ουτης', label:'-ούτης / -ουτης', suf:'ουτης'},
  {id:'υτης', label:'-ύτης / -υτης', suf:'υτης'},
  {id:'της', label:'-της', suf:'της'}
];
let chosenSuffix = 'ειτης';

function renderChips(){
  const box = $('#chips');
  box.innerHTML = '';
  for(const opt of suffixOptions){
    const b = document.createElement('button');
    b.className = 'chip';
    b.type = 'button';
    b.textContent = opt.label;
    b.setAttribute('aria-pressed', opt.suf === chosenSuffix ? 'true' : 'false');
    b.addEventListener('click', ()=>{
      chosenSuffix = opt.suf;
      renderChips();
    });
    box.appendChild(b);
  }
}

function generate(){
  const stem = $('#stem').value.trim();
  if(!stem){
    $('#genOut').innerHTML = `<span class="badge bad">Give a stem first.</span>`;
    return;
  }
  const glued = stripDiacritics(stem) + chosenSuffix;
  const sug = barytoneSuggest(glued);
  const cls = classify(glued);

  const ok = cls.suffix ? 'good' : 'warn';
  $('#genOut').innerHTML = `
    <div><span class="badge ${ok}">made</span> <span class="mono">${escapeHtml(glued)}</span></div>
    <div class="tiny">${escapeHtml(cls.barytone === false ? 'Verbal exception · oxytone' : sug.basis)} → <span class="mono">${escapeHtml(sug.suggestion)}</span></div>
  `;
}

// --- events ---
$('#btnAnalyze').addEventListener('click', render);
$('#inp').addEventListener('keydown', (e)=>{ if(e.key==='Enter') render(); });
$('#stripAcc').addEventListener('change', render);
$('#showSyll').addEventListener('change', render);
$('#showRules').addEventListener('change', render);
$('#btnClear').addEventListener('click', ()=>{ $('#inp').value=''; $('#stem').value=''; $('#genOut').replaceChildren(); render(); });
$('#btnShuffle').addEventListener('click', ()=>{
  const pick = examples[Math.floor(Math.random()*examples.length)];
  $('#inp').value = pick;
  render();
});
$('#btnGen').addEventListener('click', generate);

renderChips();
render();

candidate.js:
(()=>{
  const records=[
    {word:'καρατόμος',accent:'Penult accent',meaning:'The one who cuts off heads: Perseus, who cut off the Gorgon’s head.',group:'head'},
    {word:'καράτομος',accent:'Antepenult accent',meaning:'The one whose head has been cut off: the Gorgon.',group:'head'},
    {word:'πρωτοτόκος',accent:'Penult accent',meaning:'Active: giving birth for the first time.',group:'birth'},
    {word:'πρωτότοκος',accent:'Antepenult accent',meaning:'The one first born.',group:'birth'},
    {word:'λιθοβόλος',accent:'Penult accent',meaning:'Contrasted here with λιθόβολος; this sentence does not supply a separate gloss.',group:'stone'},
    {word:'λιθόβολος',accent:'Antepenult accent',meaning:'Contrasted here with λιθοβόλος; this sentence does not supply a separate gloss.',group:'stone'},
    {word:'πρωτόπλοος',accent:'Antepenult accent',meaning:'A stated rule takes priority: compounds derived from πλέω follow this accentuation, even when active.'},
    {word:'πολύλαλος',accent:'Antepenult accent',meaning:'A stated tendency takes priority: compounds formed with πολύ tend to have this accent.'},
    {word:'ἱππόδαμοι',accent:'Antepenult accent',meaning:'An explicit difficulty: active, yet not covered by the stated overriding rule. Cited in «ὄρνυσθ᾽ ἱππόδαμοι Τρῶες» (Il. Δ 509).'}
  ];
  const canonical=s=>s.trim().normalize('NFC').toLocaleLowerCase('el');
  const bare=s=>canonical(s).normalize('NFD').replace(/[\u0300\u0301\u0342]/g,'').normalize('NFC');
  const $=s=>document.querySelector(s), result=$('#result');
  function element(tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;}
  function card(record){const article=document.createElement('article');article.append(element('strong',record.word),element('p',record.accent,'accent'),element('p',record.meaning));return article;}
  function render(){
    result.replaceChildren();const input=canonical($('#word').value);
    if(!input){result.append(element('p','Enter a Greek example or choose one below.'));return;}
    const exact=records.find(r=>canonical(r.word)===input);
    const alternatives=records.filter(r=>bare(r.word)===bare(input));
    if(exact){
      result.append(element('h3',exact.word),element('p',exact.accent,'accent'),element('p',exact.meaning));
      if(exact.group){const pair=element('div','','pair');records.filter(r=>r.group===exact.group).forEach(r=>pair.append(card(r)));result.append(pair);}
    }else if(alternatives.length){
      result.append(element('h3','Check the accent'),element('p','The letters match a listed example, but the supplied accent does not select a cited form. Compare the spellings; meaning cannot be inferred from bare letters.'));
      const pair=element('div','','pair');alternatives.forEach(r=>pair.append(card(r)));result.append(pair);
    }else result.append(element('h3','Not a listed example'),element('p','Choose a word shown here. This passage does not establish an accent or meaning for every compound.'));
  }
  for(const record of records){const button=element('button',record.word);button.type='button';button.addEventListener('click',()=>{$('#word').value=record.word;render();});$('#examples').append(button);}
  $('#lookup').addEventListener('submit',e=>{e.preventDefault();render();});
  $('#reset').addEventListener('click',()=>{$('#word').value='';render();$('#word').focus();});render();
})();

